[CmdletBinding(SupportsShouldProcess=$true)]
param(
 [ValidateSet('Start','Continue','Status','Summarize','Stop')][string]$Action='Status',
 [ValidateRange(1,20)][int]$RunsPerArm=5,
 [ValidateRange(30,600)][int]$SampleSeconds=120,
 [ValidateRange(1,10)][int]$SampleIntervalSeconds=2,
 [switch]$AllowAutomaticReboot,
 [string]$EvidenceRoot="$PSScriptRoot\lab-evidence",
 [string]$RunDirectory,
 [string]$ControllerPath="$PSScriptRoot\..\..\controller\providers\HPNetworkHsaService.ps1"
)
Set-StrictMode -Version 2.0;$ErrorActionPreference='Stop'
$TaskName='Lacksan-EXP-066-LabHarness';$ServiceName='HPNetworkCap';$ActivePointer=Join-Path $EvidenceRoot 'active.json'
function Admin {$p=New-Object Security.Principal.WindowsPrincipal([Security.Principal.WindowsIdentity]::GetCurrent());if(-not $p.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)){throw 'Elevation required'}}
function Ensure([string]$p){if(-not(Test-Path $p)){New-Item -ItemType Directory -Path $p -Force|Out-Null}}
function WJ([string]$p,$v){$v|ConvertTo-Json -Depth 12|Set-Content $p -Encoding UTF8};function RJ([string]$p){Get-Content $p -Raw|ConvertFrom-Json}
function Med($v){$a=@($v|?{$null-ne$_}|%{[double]$_}|sort);if(!$a.Count){return $null};$m=[math]::Floor($a.Count/2);if($a.Count%2){$a[$m]}else{($a[$m-1]+$a[$m])/2}}
function Mad($v){$m=Med $v;if($null-eq$m){return $null};Med @($v|%{[math]::Abs([double]$_-$m)})}
function Boot {((Get-CimInstance Win32_OperatingSystem).LastBootUpTime).ToUniversalTime().ToString('o')}
function Paths($d){[pscustomobject]@{Harness=Join-Path $d 'harness-state.json';State=Join-Path $d 'controller-state.json';Log=Join-Path $d 'controller-events.jsonl';Summary=Join-Path $d 'summary.json'}}
function Dir {if($RunDirectory){return (Resolve-Path $RunDirectory).Path};$a=RJ $ActivePointer;(Resolve-Path $a.runDirectory).Path}
function Ctrl($a,$d){$p=Paths $d;& $ControllerPath -Action $a -StatePath $p.State -LogPath $p.Log}
function Net { $dns=$false;$https=$false;try{$dns=[bool](Resolve-DnsName www.microsoft.com -DnsOnly -ErrorAction Stop|select -First 1)}catch{};try{$r=Invoke-WebRequest 'https://www.microsoft.com' -Method Head -UseBasicParsing -TimeoutSec 10 -ErrorAction Stop;$https=$r.StatusCode-lt500}catch{};[pscustomobject]@{dns=$dns;https=$https;adapters=@(Get-NetAdapter|? Status -eq Up|select Name,InterfaceDescription,LinkSpeed);tailscale=@(Get-Service Tailscale -ErrorAction SilentlyContinue|select Name,Status,StartType);rdp=@(Get-Service TermService -ErrorAction SilentlyContinue|select Name,Status,StartType)}}
function Sample($phase,$n,$d){$boot=Boot;$svc=Get-CimInstance Win32_Service -Filter "Name='$ServiceName'";$pid0=[int]$svc.ProcessId;$p0=if($pid0){Get-Process -Id $pid0 -ErrorAction SilentlyContinue};$cpu0=if($p0){$p0.TotalProcessorTime.TotalMilliseconds}else{$null};$io0=if($pid0){Get-CimInstance Win32_Process -Filter "ProcessId=$pid0" -ErrorAction SilentlyContinue}else{$null};$net0=Net;$rows=@();$count=[math]::Ceiling($SampleSeconds/$SampleIntervalSeconds);for($i=0;$i-lt$count;$i++){$c=(Get-CimInstance Win32_PerfFormattedData_PerfOS_Processor -Filter "Name='_Total'").PercentProcessorTime;$x=(Get-CimInstance Win32_PerfFormattedData_PerfDisk_PhysicalDisk -Filter "Name='_Total'").DiskBytesPersec;$rows+=[pscustomobject]@{cpu=[double]$c;disk=[double]$x};if($i-lt$count-1){sleep $SampleIntervalSeconds}};$svc1=Get-CimInstance Win32_Service -Filter "Name='$ServiceName'";$p1=if($pid0-and[int]$svc1.ProcessId-eq$pid0){Get-Process -Id $pid0 -ErrorAction SilentlyContinue};$io1=if($p1){Get-CimInstance Win32_Process -Filter "ProcessId=$pid0" -ErrorAction SilentlyContinue};$exp=Get-Process explorer -ErrorAction SilentlyContinue|sort StartTime|select -First 1;[ordered]@{schema=1;experiment='EXP-066';phase=$phase;ordinal=$n;bootUtc=$boot;capturedUtc=(Get-Date).ToUniversalTime().ToString('o');desktopProxyMs=if($exp){($exp.StartTime.ToUniversalTime()-[datetime]$boot).TotalMilliseconds}else{$null};system=@{cpuMedian=Med @($rows|% cpu);cpuMad=Mad @($rows|% cpu);diskMedian=Med @($rows|% disk);diskMad=Mad @($rows|% disk)};service=@{startMode=$svc1.StartMode;state=$svc1.State;cpuDeltaMs=if($p1){$p1.TotalProcessorTime.TotalMilliseconds-$cpu0}else{$null};readDelta=if($io0-and$io1){[double]$io1.ReadTransferCount-[double]$io0.ReadTransferCount}else{$null};writeDelta=if($io0-and$io1){[double]$io1.WriteTransferCount-[double]$io0.WriteTransferCount}else{$null}};network=@{before=$net0;after=Net};functional=@{hpNetworkDemandStart='needs-evidence';omnissa='needs-evidence';windowsApp='needs-evidence'}}}
function Summary($d){$runs=@(Get-ChildItem $d -Filter 'run-*.json'|sort Name|%{RJ $_.FullName});$g=[ordered]@{};foreach($phase in 'Baseline','Treatment'){$r=@($runs|? phase -eq $phase);$g[$phase]=@{runs=$r.Count;desktopProxyMs=@{median=Med @($r|% desktopProxyMs);mad=Mad @($r|% desktopProxyMs)};cpuMedian=@{median=Med @($r|%{$_.system.cpuMedian});mad=Mad @($r|%{$_.system.cpuMedian})};diskMedian=@{median=Med @($r|%{$_.system.diskMedian});mad=Mad @($r|%{$_.system.diskMedian})};serviceCpuMs=@{median=Med @($r|%{$_.service.cpuDeltaMs});mad=Mad @($r|%{$_.service.cpuDeltaMs})}}};$s=@{schema=1;experiment='EXP-066';generatedUtc=(Get-Date).ToUniversalTime().ToString('o');groups=$g;limitations=@('desktopProxyMs uses Explorer start as readiness proxy','HP application demand-start and protected app usability require observation')};WJ (Join-Path $d 'summary.json') $s;$s}
function Task($d){$exe=(Get-Command powershell.exe).Source;$args="-NoProfile -ExecutionPolicy Bypass -File `"$PSCommandPath`" -Action Continue -RunDirectory `"$d`" -EvidenceRoot `"$EvidenceRoot`" -ControllerPath `"$ControllerPath`"";$a=New-ScheduledTaskAction -Execute $exe -Argument $args;$u=[Security.Principal.WindowsIdentity]::GetCurrent().Name;$t=New-ScheduledTaskTrigger -AtLogOn -User $u;$p=New-ScheduledTaskPrincipal -UserId $u -LogonType Interactive -RunLevel Highest;Register-ScheduledTask -TaskName $TaskName -Action $a -Trigger $t -Principal $p -Force|Out-Null}
function Untask {Unregister-ScheduledTask -TaskName $TaskName -Confirm:$false -ErrorAction SilentlyContinue}
function Reboot {if($AllowAutomaticReboot){Restart-Computer -Force}else{'Reboot required; continuation resumes at next logon.'}}
Admin;if(-not(Test-Path $ControllerPath)){throw 'Controller missing'}
switch($Action){
'Start'{Ensure $EvidenceRoot;if(Test-Path $ActivePointer){throw 'Active run exists'};$null=Ctrl Check $EvidenceRoot;if($WhatIfPreference){return};$d=Join-Path $EvidenceRoot ((Get-Date).ToUniversalTime().ToString('yyyyMMdd-HHmmss'));Ensure $d;$null=Ctrl Capture $d;$null=Ctrl DryRun $d;WJ (Paths $d).Harness @{phase='Baseline';completed=0;runsPerArm=$RunsPerArm;lastBoot=$null};WJ $ActivePointer @{runDirectory=$d};Task $d;Reboot}
'Continue'{$d=Dir;$p=Paths $d;$s=RJ $p.Harness;$b=Boot;if($s.lastBoot-eq$b){throw 'Duplicate boot refused'};if($s.phase-eq'Treatment'){$null=Ctrl VerifyReboot $d};$n=[int]$s.completed+1;$r=Sample $s.phase $n $d;WJ (Join-Path $d ("run-{0}-{1:D2}.json"-f$s.phase,$n)) $r;$s.completed=$n;$s.lastBoot=$b;if($s.completed-ge$s.runsPerArm){if($s.phase-eq'Baseline'){$s.phase='Treatment';$s.completed=0;$null=Ctrl Apply $d;$null=Ctrl Verify $d}else{$null=Ctrl Rollback $d;$out=Summary $d;Untask;Remove-Item $ActivePointer -Force;WJ $p.Harness $s;return $out}};WJ $p.Harness $s;Reboot}
'Status'{if(Test-Path $ActivePointer){RJ (Paths (Dir)).Harness}else{@{active=$false}}}
'Summarize'{Summary (Dir)}
'Stop'{$d=Dir;$null=Ctrl Rollback $d;Untask;Remove-Item $ActivePointer -Force -ErrorAction SilentlyContinue;@{stopped=$true;runDirectory=$d}}
}